class Encrypter { unordered_map<char,string> mapping;unordered_map<string,int> frequency;public:Encrypter(vector<char>& keys,vector<string>& values,vector<string>& dictionary){for(int i=0;i<(int)keys.size();++i)mapping[keys[i]]=values[i];for(string& word:dictionary){string encrypted=encrypt(word);if(!encrypted.empty())++frequency[encrypted];}}string encrypt(string word1){string result;for(char ch:word1){if(!mapping.count(ch))return "";result+=mapping[ch];}return result;}int decrypt(string word2){return frequency[word2];} };
